// FUNCTION: BFME2 0x002C7362 size=60 name=?isAnyWithinTargetPitch@WeaponSet@@ABE_NPBVObject@@0@Z evidence=N:ledger
Bool WeaponSet::isAnyWithinTargetPitch(const Object *obj, const Object *victim) const
{
	if (!m_hasPitchLimit)
		return true;

	for (Int s = 0; s < WEAPONSLOT_COUNT; ++s)
	{
		const Weapon *weapon = m_weapons[s];
		if (weapon && weapon->isWithinTargetPitch(obj, victim))
			return true;
	}
	return false;
}

// FUNCTION: BFME2 0x002C739E size=48 name=?reloadAllAmmo@WeaponSet@@QAEXPBVObject@@_N@Z evidence=N:ledger
void WeaponSet::reloadAllAmmo(const Object *obj, Bool now)
{
	for (Int s = 0; s < WEAPONSLOT_COUNT; ++s)
	{
		Weapon *weapon = m_weapons[s];
		if (weapon)
		{
			if (now)
				weapon->loadAmmoNow(obj);
			else
				weapon->reloadAmmo(obj);
		}
	}
}

// FUNCTION: BFME2 0x002C73CE size=41 name=?isOutOfAmmo@WeaponSet@@QBE_NXZ evidence=N:ledger
bool WeaponSet::isOutOfAmmo() const
{
	for (int s = 0; s < 6; ++s)
	{
		const Weapon *weapon = m_weapons[s];
		if (weapon == 0)
			continue;
		if (weapon->getStatus() != OUT_OF_AMMO)
			return false;
	}
	return true;
}

