// FUNCTION: BFME2 0x002C8872 size=572 name=?xfer@WeaponSet@@MAEXPAVXfer@@@Z evidence=N:ledger
// Written from retail's disassembly. Nothing on a light CRC; the template set goes by its
// ThingTemplate's name and the WeaponSetFlags it was chosen with (a missing template or
// set is XferException 5); then each slot's weapon behind a presence flag (a load makes a
// missing weapon from the set's template for that slot, falling back to the primary one;
// a slot saved empty deletes what the load finds), the six override bytes and the rest.
void WeaponSet::xfer(Xfer *xfer)
{
	if (xfer->IsLightCRC())
		return;
	xfer->Version1();

	if (xfer->IsLoading())
	{
		AsciiString templateName;
		WeaponSetFlags flags;
		*xfer == templateName;
		flags.xfer(xfer);
		if (templateName.isEmpty())
		{
			m_curWeaponTemplateSet = NULL;
		}
		else
		{
			const ThingTemplate *thingTemplate = TheThingFactory->findTemplate(templateName);
			if (thingTemplate == NULL)
				throw XferException(5, 0);
			m_curWeaponTemplateSet = thingTemplate->findWeaponTemplateSet(flags);
			if (m_curWeaponTemplateSet == NULL)
				throw XferException(5, 0);
		}
	}
	else
	{
		AsciiString templateName;
		WeaponSetFlags flags;
		if (m_curWeaponTemplateSet != NULL)
		{
			const ThingTemplate *thingTemplate = m_curWeaponTemplateSet->m_thingTemplate;
			if (thingTemplate == NULL)
				throw XferException(5, 0);
			templateName = thingTemplate->getName();
			flags = m_curWeaponTemplateSet->m_types;
		}
		*xfer == templateName;
		flags.xfer(xfer);
	}

	for (Int s = 0; s < WEAPONSLOT_COUNT; ++s)
	{
		Bool hasWeapon = m_weapons[s] != NULL;
		*xfer == hasWeapon;
		if (hasWeapon)
		{
			if (xfer->IsLoading() && m_weapons[s] == NULL)
			{
				const WeaponTemplate *weaponTemplate = m_curWeaponTemplateSet->m_template[s];
				if (weaponTemplate == NULL)
					weaponTemplate = m_curWeaponTemplateSet->m_template[PRIMARY_WEAPON];
				m_weapons[s] = TheWeaponStore->allocateNewWeapon(weaponTemplate, (WeaponSlotType)s);
			}
			*xfer == *m_weapons[s];
		}
		else if (m_weapons[s] != NULL)
		{
			::delete m_weapons[s];
			m_weapons[s] = NULL;
		}
	}

	for (Int j = 0; j < WEAPONSLOT_COUNT; ++j)
		*xfer == m_slotFlags[j];

	xfer->XferRawBytes(&m_currentWeapon, sizeof(m_currentWeapon));
	xfer->XferRawBytes(&m_currentWeaponLockedStatus, sizeof(m_currentWeaponLockedStatus));
	*xfer == m_filledWeaponSlotMask;
	*xfer == m_totalAntiMask;
	*xfer == m_totalDamageTypeMask;
	*xfer == m_hasDamageWeapon;
	*xfer == m_hasPitchLimit;
	XferObjectID(xfer, &m_ownerID);
}

// FUNCTION: BFME2 0x002C8AAE size=237 name=?setWeaponLock@WeaponSet@@QAE_NW4WeaponSlotType@@W4WeaponLockType@@@Z evidence=N:ledger
Bool WeaponSet::setWeaponLock(WeaponSlotType weaponSlot, WeaponLockType lockType)
{
	Object *owner = TheGameLogic->findObjectByID(m_ownerID);
	if (lockType != NOT_LOCKED && m_weapons[weaponSlot] != NULL)
	{
		if (lockType == LOCKED_PERMANENTLY)
		{
			m_currentWeaponLockedStatus = lockType;
			m_currentWeapon = weaponSlot;
		}
		else if (lockType == LOCKED_TEMPORARILY && m_currentWeaponLockedStatus != LOCKED_PERMANENTLY)
		{
			m_currentWeaponLockedStatus = LOCKED_TEMPORARILY;
			m_currentWeapon = weaponSlot;
		}

		if (owner != NULL)
			owner->rva001E42F2((const int *)&ModelConditionFlags(ModelConditionFlags::kInit,
				MODELCONDITION_WEAPONLOCK_PRIMARY, MODELCONDITION_WEAPONLOCK_SECONDARY, MODELCONDITION_WEAPONLOCK_TERTIARY,
				MODELCONDITION_WEAPONLOCK_QUATERNARY, MODELCONDITION_WEAPONLOCK_QUINARY));

		switch (m_currentWeapon)
		{
			case PRIMARY_WEAPON:
				if (owner != NULL)
					owner->setModelConditionState(MODELCONDITION_WEAPONLOCK_PRIMARY);
				break;
			case SECONDARY_WEAPON:
				if (owner != NULL)
					owner->setModelConditionState(MODELCONDITION_WEAPONLOCK_SECONDARY);
				break;
			case TERTIARY_WEAPON:
				if (owner != NULL)
					owner->setModelConditionState(MODELCONDITION_WEAPONLOCK_TERTIARY);
				break;
			case QUATERNARY_WEAPON:
				if (owner != NULL)
					owner->setModelConditionState(MODELCONDITION_WEAPONLOCK_QUATERNARY);
				break;
			case QUINARY_WEAPON:
				if (owner != NULL)
					owner->setModelConditionState(MODELCONDITION_WEAPONLOCK_QUINARY);
				break;
		}
		return true;
	}
	return false;
}

// FUNCTION: BFME2 0x002C8B9B size=107 name=?releaseWeaponLock@WeaponSet@@QAEXW4WeaponLockType@@@Z evidence=N:ledger
void WeaponSet::releaseWeaponLock(WeaponLockType lockType)
{
	Object *owner = TheGameLogic->findObjectByID(m_ownerID);
	if (m_currentWeaponLockedStatus != NOT_LOCKED)
	{
		if (lockType == LOCKED_PERMANENTLY)
		{
			m_currentWeaponLockedStatus = NOT_LOCKED;
			if (owner != NULL)
				owner->rva001E42F2((const int *)&ModelConditionFlags(ModelConditionFlags::kInit,
					MODELCONDITION_WEAPONLOCK_PRIMARY, MODELCONDITION_WEAPONLOCK_SECONDARY, MODELCONDITION_WEAPONLOCK_TERTIARY,
					MODELCONDITION_WEAPONLOCK_QUATERNARY, MODELCONDITION_WEAPONLOCK_QUINARY));
		}
		else if (lockType == LOCKED_TEMPORARILY)
		{
			if (m_currentWeaponLockedStatus == LOCKED_TEMPORARILY)
			{
				m_currentWeaponLockedStatus = NOT_LOCKED;
				if (owner != NULL)
					owner->rva001E42F2((const int *)&ModelConditionFlags(ModelConditionFlags::kInit,
						MODELCONDITION_WEAPONLOCK_PRIMARY, MODELCONDITION_WEAPONLOCK_SECONDARY, MODELCONDITION_WEAPONLOCK_TERTIARY,
						MODELCONDITION_WEAPONLOCK_QUATERNARY, MODELCONDITION_WEAPONLOCK_QUINARY));
			}
		}
	}
}

