// FUNCTION: BFME2 0x002C8C7B size=28 name=?parseWeaponTemplateSet@WeaponTemplateSet@@QAEXPAVINI@@PBVThingTemplate@@@Z evidence=N:ledger
void WeaponTemplateSet::parseWeaponTemplateSet(INI *ini, const ThingTemplate *tmpl)
{
	// The table at VA 0x00C00A90, read back entry by entry from the image.
	static const FieldParse myFieldParse[] =
	{
		{ "Conditions", WeaponSetFlags::parseFromINI, NULL, offsetof(WeaponTemplateSet, m_types) },
		{ "Weapon", WeaponTemplateSet::parseWeapon, NULL, 0 },
		{ "AutoChooseSources", WeaponTemplateSet::parseAutoChoose, NULL, 0 },
		{ "PreferredAgainst", WeaponTemplateSet::parsePreferredAgainst, NULL, 0 },
		{ "OnlyAgainst", WeaponTemplateSet::parseOnlyAgainst, NULL, 0 },
		{ "OnlyInCondition", WeaponTemplateSet::parseOnlyInCondition, NULL, 0 },
		{ "ShareWeaponReloadTime", INI::parseBool, NULL, offsetof(WeaponTemplateSet, m_isReloadTimeShared) },
		{ "WeaponLockSharedAcrossSets", INI::parseBool, NULL, offsetof(WeaponTemplateSet, m_isWeaponLockSharedAcrossSets) },
		{ "ReadyStatusSharedWithinSet", INI::parseBool, NULL, offsetof(WeaponTemplateSet, m_isReadyStatusSharedWithinSet) },
		{ "DefaultWeaponChoiceCritera", INI::parseIndexList, TheWeaponChoiceCriteriaNames, offsetof(WeaponTemplateSet, m_defaultWeaponChoiceCriteria) },
		{ 0, 0, 0, 0 }
	};
	ini->initFromINI(this, myFieldParse);
	m_thingTemplate = tmpl;
}

// FUNCTION: BFME2 0x002C8C97 size=418 name=?updateWeaponSet@WeaponSet@@QAEXPBVObject@@@Z evidence=N:ledger
// Zero Hour's updateWeaponSet with BFME's carried-over firing state: when both the old and
// the new set share reload times, each old weapon's state is saved and handed to the new
// weapon of the same template; the weapons are looked up by name key and own the object's ID.
void WeaponSet::updateWeaponSet(const Object *obj)
{
	const WeaponTemplateSet *set = obj->getTemplate()->findWeaponTemplateSet(obj->getWeaponSetFlags());
	if (set != NULL && set != m_curWeaponTemplateSet)
	{
		SavedWeaponState states[WEAPONSLOT_COUNT];
		SavedWeaponState *saved = NULL;
		if (m_curWeaponTemplateSet != NULL && m_curWeaponTemplateSet->m_isReloadTimeShared && set->m_isReloadTimeShared)
		{
			saved = states;
			for (Int i = WEAPONSLOT_COUNT - 1; i >= PRIMARY_WEAPON; --i)
			{
				if (m_weapons[i] != NULL)
					states[i].copyFrom(m_weapons[i]);
			}
		}

		if (!set->m_isWeaponLockSharedAcrossSets)
		{
			releaseWeaponLock(LOCKED_PERMANENTLY);
			m_currentWeapon = PRIMARY_WEAPON;
		}

		m_filledWeaponSlotMask = 0;
		m_totalAntiMask = 0;
		m_totalDamageTypeMask = 0;
		m_hasPitchLimit = false;
		m_hasDamageWeapon = false;
		for (Int i = WEAPONSLOT_COUNT - 1; i >= PRIMARY_WEAPON; --i)
		{
			if (m_weapons[i] != NULL)
			{
				::delete m_weapons[i];
				m_weapons[i] = NULL;
			}
			if (set->m_template[i] != NULL)
			{
				const WeaponTemplate *tmpl = TheWeaponStore->findWeaponTemplatePrivate(set->m_template[i]->m_nameKey);
				if (tmpl != NULL)
				{
					m_weapons[i] = TheWeaponStore->allocateNewWeapon(tmpl, (WeaponSlotType)i);
					m_weapons[i]->setOwnerID(obj->getID());
					m_weapons[i]->rva002CE226(obj, saved);
					m_filledWeaponSlotMask |= (1 << i);
					m_totalAntiMask |= m_weapons[i]->getTemplate()->m_antiMask;
					m_totalDamageTypeMask |= (1 << m_weapons[i]->getTemplate()->m_damageType);
					if (m_weapons[i]->m_pitchLimited)
						m_hasPitchLimit = true;
					if (m_weapons[i]->getTemplate()->m_hasDamageNugget)
						m_hasDamageWeapon = true;
				}
			}
		}
		m_curWeaponTemplateSet = set;
		m_ownerID = obj->getID();
	}
}

